namespace airi { namespace {
std::wstring W(const std::string&s){if(s.empty())return{};int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring o(n,L'\0');MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),o.data(),n);return o;}
std::wstring Q(const std::wstring&s){return L"\""+s+L"\"";}
std::filesystem::path appdir(){wchar_t p[32768]{};GetModuleFileNameW(nullptr,p,32768);return std::filesystem::path(p).parent_path();}
std::wstring fmt(const std::string&q,bool ff){if(q=="audio")return L"ba/b";auto progressive=[&](int h){return L"best[height<="+std::to_wstring(h)+L"][vcodec!=none][acodec!=none]/best[height<="+std::to_wstring(h)+L"]/best";};int h=q=="360p"?360:q=="720p"?720:q=="1080p"?1080:q=="1440p"?1440:(q=="2160p"||q=="4k")?2160:0;if(!ff)return h?progressive(h):L"best[vcodec!=none][acodec!=none]/best";if(h)return L"bv*[height<="+std::to_wstring(h)+L"]+ba/b[height<="+std::to_wstring(h)+L"]";return L"bv*+ba/b";}
std::wstring clean(std::wstring v){v.erase(std::remove(v.begin(),v.end(),L'\r'),v.end());v.erase(std::remove(v.begin(),v.end(),L'\n'),v.end());std::wstring o;for(auto c:v){if(c==L'\"')o+=L"\\\"";else o+=c;}return o;}
}
std::filesystem::path MediaWorker::tools_directory(){return appdir()/L"tools";}
std::filesystem::path MediaWorker::tool_path(){return tools_directory()/L"yt-dlp.exe";}
bool MediaWorker::available(){return std::filesystem::exists(tool_path());}
bool MediaWorker::download(const MediaRequest&r,Callback cb){auto tools=tools_directory(),yt=tool_path(),ff=tools/L"ffmpeg.exe",deno=tools/L"deno.exe";if(!std::filesystem::exists(yt)){if(cb)cb({0,"Failed","AIRI media engine is missing."});return false;}bool hasff=std::filesystem::exists(ff),hasdeno=std::filesystem::exists(deno);std::error_code ec;std::filesystem::create_directories(r.save_directory,ec);std::wstring cmd=Q(yt)+L" --ignore-config --newline --no-playlist --windows-filenames --no-color --progress-template \"download:%(progress._percent_str)s\" --output \"%(title).180B [%(id)s].%(ext)s\" -P "+Q(r.save_directory.wstring())+L" -f "+Q(fmt(r.quality,hasff));if(hasdeno)cmd+=L" --js-runtimes "+Q(L"deno:"+deno.wstring());if(hasff)cmd+=L" --ffmpeg-location "+Q(tools.wstring())+L" --merge-output-format mp4";if(!r.user_agent.empty())cmd+=L" --user-agent "+Q(clean(W(r.user_agent)));if(!r.referer.empty())cmd+=L" --referer "+Q(clean(W(r.referer)));if(!r.cookie.empty())cmd+=L" --add-headers "+Q(L"Cookie:"+clean(W(r.cookie)));cmd+=L" "+Q(W(r.page_url));SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE rd{},wr{};if(!CreatePipe(&rd,&wr,&sa,0)){if(cb)cb({0,"Failed","Could not create media pipe."});return false;}SetHandleInformation(rd,HANDLE_FLAG_INHERIT,0);STARTUPINFOW si{};si.cb=sizeof(si);si.dwFlags=STARTF_USESTDHANDLES|STARTF_USESHOWWINDOW;si.wShowWindow=SW_HIDE;si.hStdOutput=wr;si.hStdError=wr;si.hStdInput=GetStdHandle(STD_INPUT_HANDLE);PROCESS_INFORMATION pi{};std::vector<wchar_t>mutableCmd(cmd.begin(),cmd.end());mutableCmd.push_back(L'\0');BOOL ok=CreateProcessW(yt.c_str(),mutableCmd.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW|CREATE_UNICODE_ENVIRONMENT,nullptr,tools.c_str(),&si,&pi);CloseHandle(wr);if(!ok){CloseHandle(rd);if(cb)cb({0,"Failed","Could not start media engine."});return false;}if(cb)cb({0,"Preparing","AIRI media engine started silently."});std::string pending,last;std::array<char,4096>b{};for(;;){DWORD avail=0;if(!PeekNamedPipe(rd,nullptr,0,nullptr,&avail,nullptr))break;if(avail){DWORD got=0;if(!ReadFile(rd,b.data(),(DWORD)std::min<std::size_t>(b.size(),avail),&got,nullptr)||!got)break;pending.append(b.data(),got);std::size_t p;while((p=pending.find_first_of("\r\n"))!=std::string::npos){auto line=pending.substr(0,p);pending.erase(0,p+1);if(line.empty())continue;last=line;if(line.rfind("download:",0)==0){auto pct=line.substr(9);pct.erase(std::remove_if(pct.begin(),pct.end(),[](char c){return c=='%'||c==' ';}),pct.end());try{if(cb)cb({(int)std::stod(pct),"Downloading",line});}catch(...){}}else if(line.find("ERROR:")!=std::string::npos){if(cb)cb({0,"Failed",line});}else if(cb)cb({0,"Working",line});}}auto wait=WaitForSingleObject(pi.hProcess,avail?0:100);if(wait==WAIT_OBJECT_0&&!avail)break;}DWORD code=1;GetExitCodeProcess(pi.hProcess,&code);CloseHandle(rd);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);if(cb)cb({code?0:100,code?"Failed":"Completed",code?(last.empty()?"Media engine failed.":last):"Media download completed."});return code==0;}
}
#endif
